# Iterar sobre dict
puntos = {"Ana": 95, "Bob": 87, "Carlos": 92}
for nombre, pts in puntos.items():
    print(f"{nombre}: {pts}")

ganador = max(puntos, key=puntos.get)
print(f"Ganador: {ganador}")

cache: dict = {}

def fibonacci(n: int) -> int:
    if n in cache:
        return cache[n]
    if n <= 1:
        return n
    cache[n] = fibonacci(n-1) + fibonacci(n-2)
    return cache[n]

print(fibonacci(10))  # 55

from typing import Dict, Set

def agrupar_por_longitud(palabras: list[str]) -> Dict[int, Set[str]]:
    resultado: Dict[int, Set[str]] = {}
    for p in palabras:
        resultado.setdefault(len(p), set()).add(p)
    return resultado

print(agrupar_por_longitud(["hi", "hola", "mundo", "ok"]))

persona = {"nombre": "Ana", "edad": 30, "ciudad": "Madrid"}
print(persona["nombre"])         # Ana
print(persona.get("pais", "N/A")) # N/A

