datos = [("A", 1), ("B", 2), ("A", 3), ("B", 4)]
for clave, valor in datos:
    grupos[clave].append(valor)
print(dict(grupos))  # {'A': [1, 3], 'B': [2, 4]}

persona = {"nombre": "Ana", "edad": 30, "ciudad": "Madrid"}
print(persona["nombre"])         # Ana
print(persona.get("pais", "N/A")) # N/A

nums = {1, 2, 3, 4, 5}
pares = {2, 4, 6, 8}
print(nums & pares)   # {2, 4}   intersección
print(nums | pares)   # {1, 2, 3, 4, 5, 6, 8}  unión
print(nums - pares)   # {1, 3, 5}  diferencia

from typing import Dict, Set

def agrupar_por_longitud(palabras: list[str]) -> Dict[int, Set[str]]:
    resultado: Dict[int, Set[str]] = {}
    for p in palabras:
        resultado.setdefault(len(p), set()).add(p)
    return resultado

print(agrupar_por_longitud(["hi", "hola", "mundo", "ok"]))

config = {
    "host": "localhost",
    "port": 8080,
    "debug": True,
    "db": {"name": "app", "pool": 5}
}
print(config["db"]["name"])  # app
config.update({"port": 9000, "debug": False})
print(config["port"])  # 9000

cache: dict = {}

def fibonacci(n: int) -> int:
    if n in cache:
        return cache[n]
    if n <= 1:
        return n
    cache[n] = fibonacci(n-1) + fibonacci(n-2)
    return cache[n]

print(fibonacci(10))  # 55

